#pragma once

#include <cstdint>

#include "activities/Activity.h"

// Avatar creator: layers Notion-style avatar parts (face, hair, eyes, ...) from
// the SD pack /.crosspoint/avatars/parts.bin, generated by scripts/gen_avatars.py
// (CC0 art, not bundled in flash). Side Up/Down pick the part, Left/Right cycle
// it, Confirm randomizes, holding Confirm saves a full-screen portrait to /sleep
// as a wallpaper BMP, Back exits. Without the pack a placeholder face is shown.
class SketchActivity final : public Activity {
 public:
  explicit SketchActivity(GfxRenderer& renderer, MappedInputManager& mappedInput)
      : Activity("Sketch", renderer, mappedInput) {}

  void onEnter() override;
  void loop() override;
  void render(RenderLock&&) override;

  static constexpr int MAX_CATEGORIES = 10;

 private:
  uint8_t counts[MAX_CATEGORIES] = {};  // options per pack category
  uint8_t choice[MAX_CATEGORIES] = {};
  uint8_t categoryCount = 0;
  uint16_t boxW = 0, boxH = 0;
  bool packReady = false;
  uint8_t part = 0;  // index into the UI order
  uint32_t rng = 1;

  // Guarded by the render lock.
  bool fullRedraw = true;
  bool saveRequested = false;
  const char* toast = nullptr;

  bool loadPack();
  void randomize();
  void cycle(int delta);
  int category() const;
  bool saveWallpaper();
  void drawAvatar(int x, int y) const;
  void drawPlaceholder(int x, int y) const;
  void drawHeader() const;
  int avatarY() const;
  int captionY() const;
};
